import { Reference } from '@ethersphere/core-sdk';
import { GetAllPinsResponse } from "../types/schema/pinning.js";
import { UploadResultBody } from "../types/schema/upload.js";
import { http } from "../utils/http.js";
const PINNING_ENDPOINT = 'pins';
/** Pins local data with the given reference. */
export async function pin(requestOptions, reference) {
  await http(requestOptions, {
    method: 'post',
    responseType: 'json',
    url: `${PINNING_ENDPOINT}/${reference}`
  });
}
/** Unpins local data with the given reference. */
export async function unpin(requestOptions, reference) {
  await http(requestOptions, {
    method: 'delete',
    responseType: 'json',
    url: `${PINNING_ENDPOINT}/${reference}`
  });
}
/** Gets the list of all locally pinned references. */
export async function getAllPins(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    responseType: 'json',
    url: PINNING_ENDPOINT
  });
  const {
    references
  } = GetAllPinsResponse.parse(response.data);
  return (references ?? []).map(x => new Reference(x));
}
/** Gets the pinning status of the chunk with the given reference. */
export async function getPin(requestOptions, reference) {
  const response = await http(requestOptions, {
    method: 'get',
    responseType: 'json',
    url: `${PINNING_ENDPOINT}/${reference}`
  });
  return UploadResultBody.parse(response.data);
}